    public static function doSelectJoinAllExceptBpmnSimulation(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        // $criteria->getDbName() will return the same object if not set to another value
        // so == check is okay and faster
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(WorkflowInstancePeer::DATABASE_NAME);
        }

        WorkflowInstancePeer::addSelectColumns($criteria);
        $startcol2 = WorkflowInstancePeer::NUM_HYDRATE_COLUMNS;

        BpmnProcessPeer::addSelectColumns($criteria);
        $startcol3 = $startcol2 + BpmnProcessPeer::NUM_HYDRATE_COLUMNS;

        WorkflowStatusPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + WorkflowStatusPeer::NUM_HYDRATE_COLUMNS;

        UsuarioPeer::addSelectColumns($criteria);
        $startcol5 = $startcol4 + UsuarioPeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(WorkflowInstancePeer::BPMNPROCESS_ID, BpmnProcessPeer::BPMNPROCESS_ID, $join_behavior);

        $criteria->addJoin(WorkflowInstancePeer::WORKFLOWSTATUS_ID, WorkflowStatusPeer::WORKFLOWSTATUS_ID, $join_behavior);

        $criteria->addJoin(WorkflowInstancePeer::USUARIO_ID, UsuarioPeer::USUARIO_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseWorkflowInstancePeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = WorkflowInstancePeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = WorkflowInstancePeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {
                $cls = WorkflowInstancePeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                WorkflowInstancePeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined BpmnProcess rows

                $key2 = BpmnProcessPeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = BpmnProcessPeer::getInstanceFromPool($key2);
                    if (!$obj2) {
    
                        $cls = BpmnProcessPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol2);
                    BpmnProcessPeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

                // Add the $obj1 (WorkflowInstance) to the collection in $obj2 (BpmnProcess)
                $obj2->addWorkflowInstance($obj1);

            } // if joined row is not null

                // Add objects for joined WorkflowStatus rows

                $key3 = WorkflowStatusPeer::getPrimaryKeyHashFromRow($row, $startcol3);
                if ($key3 !== null) {
                    $obj3 = WorkflowStatusPeer::getInstanceFromPool($key3);
                    if (!$obj3) {
    
                        $cls = WorkflowStatusPeer::getOMClass();

                    $obj3 = new $cls();
                    $obj3->hydrate($row, $startcol3);
                    WorkflowStatusPeer::addInstanceToPool($obj3, $key3);
                } // if $obj3 already loaded

                // Add the $obj1 (WorkflowInstance) to the collection in $obj3 (WorkflowStatus)
                $obj3->addWorkflowInstance($obj1);

            } // if joined row is not null

                // Add objects for joined Usuario rows

                $key4 = UsuarioPeer::getPrimaryKeyHashFromRow($row, $startcol4);
                if ($key4 !== null) {
                    $obj4 = UsuarioPeer::getInstanceFromPool($key4);
                    if (!$obj4) {
    
                        $cls = UsuarioPeer::getOMClass();

                    $obj4 = new $cls();
                    $obj4->hydrate($row, $startcol4);
                    UsuarioPeer::addInstanceToPool($obj4, $key4);
                } // if $obj4 already loaded

                // Add the $obj1 (WorkflowInstance) to the collection in $obj4 (Usuario)
                $obj4->addWorkflowInstance($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }

